Rules.InvariantScript:
Set(varInspectionId, "FI-" & Text(Now(), "[$-en-US]yyyymmddhhmmss") & "-" & Left(Text(GUID()), 8));
Set(varItemNumber, Blank());
Set(varSerialNumber, Blank());
NewForm(Form1);
UpdateContext({ newMode: true, editMode: false, itemSelected: true })

Set(varSavedInspection, Form1.LastSubmit);

ForAll(
    Sequence(CountRows(DataCardValue15.Attachments)) As n,
    With(
        {
            p: Last(FirstN(DataCardValue15.Attachments, n.Value))
        },
        Patch(
            FurnitureInspectionPhotos,
            Defaults(FurnitureInspectionPhotos),
            {
                Title: "Inspection-" & varSavedInspection.ID & "-" & Text(n.Value),
                InspectionListID: varSavedInspection.ID,
                InspectionID: varSavedInspection.InspectionID,
                PhotoIndex: n.Value,
                PhotoName: p.Name
            }
        )
    )
);

Patch(
    FurnitureInspections,
    varSavedInspection,
    {
        PhotoCount: CountRows(DataCardValue15.Attachments),
        ReportDate: Today()
    }
);

UpdateContext({ CurrentItem: varSavedInspection, editMode: false, newMode: false, itemSelected: true });
Set(varInspectionId, Blank());
Set(varItemNumber, Blank());
Set(varSerialNumber, Blank());
Notify("Inspection saved: " & varSavedInspection.InspectionID, NotificationType.Success)
